export const HYPOTHESES=[{"id":"H01","evidence":"E01","insight":"Consumers can accept an offer only within personal conditions.","requirement":"Show delivery fee, ETA, allowed categories and courier safeguards before checkout.","hypothesis":"A contextual offer can outperform one-size-fits-all messaging on qualified interest.","metric":"eligible_offer_to_checkout","guardrail":"complaint_rate","status":"Design hypothesis; untested"},{"id":"H02","evidence":"E02","insight":"Category choice changes what feels acceptable.","requirement":"Allow category-specific delivery offer configuration.","hypothesis":"Category-aware offers improve qualified intent compared with a single offer.","metric":"qualified_intent_by_category","guardrail":"unexpected_substitution_rate","status":"Design hypothesis; untested"},{"id":"H03","evidence":"E03","insight":"Home and work are different order contexts.","requirement":"Capture delivery context before displaying eligibility.","hypothesis":"Context-aware options reduce invalid attempts and post-checkout cancellation.","metric":"eligible_checkout_by_context","guardrail":"late_delivery_rate","status":"Design hypothesis; untested"},{"id":"H04","evidence":"E04","insight":"Courier treatment can be a non-negotiable condition.","requirement":"Publish specific, verifiable courier safeguards and prohibit offers breaching the minimum standard.","hypothesis":"Transparent safeguards improve qualified intent among customers who condition their use on worker treatment.","metric":"qualified_intent_under_safeguards","guardrail":"courier_safety_incidents","status":"Design hypothesis; untested"},{"id":"H05","evidence":"E05","insight":"Delivery feasibility may depend on geography.","requirement":"Check service-zone feasibility and operational capacity before promising an ETA.","hypothesis":"Zone-aware promises reduce service failures.","metric":"promise_kept_rate_by_zone","guardrail":"unfulfilled_order_rate","status":"Design hypothesis; untested"},{"id":"H06","evidence":"E01","insight":"Research themes need testable business decisions.","requirement":"Log eligibility conditions and outcomes with privacy minimisation.","hypothesis":"Structured instrumentation reveals which restrictions cause avoidable dropout.","metric":"eligibility_reason_distribution","guardrail":"data_retention_breaches","status":"Design hypothesis; untested"}];
